CREATE TABLE crm_brokerages (id text PRIMARY KEY, name text NOT NULL, lofty_team_id text NOT NULL UNIQUE);
CREATE TABLE crm_members (id text PRIMARY KEY, brokerage_id text NOT NULL REFERENCES crm_brokerages(id), subject text NOT NULL UNIQUE, label text NOT NULL, lofty_user_id text NOT NULL, role text NOT NULL CHECK (role IN ('agent', 'leader')), active boolean NOT NULL DEFAULT true, UNIQUE (id, brokerage_id));
CREATE UNIQUE INDEX crm_member_account ON crm_members (brokerage_id, lofty_user_id);
CREATE TABLE crm_connections (id text PRIMARY KEY, brokerage_id text NOT NULL, member_id text NOT NULL UNIQUE, provider text NOT NULL DEFAULT 'lofty' CHECK (provider = 'lofty'), status text NOT NULL DEFAULT 'disconnected', tokens text, identity jsonb, capabilities jsonb NOT NULL DEFAULT '[]', epoch integer NOT NULL DEFAULT 0, last_sync_at timestamptz, last_attempt_at timestamptz, error_code text, cooldown_until timestamptz, scan_id text, scan_offset integer NOT NULL DEFAULT 0, scan_started_at timestamptz, FOREIGN KEY (member_id, brokerage_id) REFERENCES crm_members(id, brokerage_id));
CREATE TABLE crm_oauth_states (hash text PRIMARY KEY, browser_hash text NOT NULL, member_id text NOT NULL REFERENCES crm_members(id), epoch integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE crm_records (id text PRIMARY KEY, connection_id text NOT NULL REFERENCES crm_connections(id), kind text NOT NULL CHECK (kind IN ('lead', 'note', 'task', 'activity', 'transaction')), external_id text NOT NULL, lead_id text NOT NULL, data jsonb NOT NULL, hash text NOT NULL, source_updated_at timestamptz, observed_at timestamptz NOT NULL, scan_id text, status text NOT NULL DEFAULT 'active');
CREATE UNIQUE INDEX crm_record_external ON crm_records (connection_id, kind, external_id);
CREATE INDEX crm_records_lead ON crm_records (connection_id, lead_id);
CREATE TABLE crm_sync_runs (id text PRIMARY KEY, connection_id text NOT NULL REFERENCES crm_connections(id), started_at timestamptz NOT NULL, finished_at timestamptz, status text NOT NULL, count integer NOT NULL DEFAULT 0, error_code text, detail text);
CREATE TABLE crm_writes (id text PRIMARY KEY, connection_id text NOT NULL REFERENCES crm_connections(id), request_id text NOT NULL, epoch integer NOT NULL, proposal jsonb NOT NULL, proposed_by text NOT NULL REFERENCES crm_members(id), created_at timestamptz NOT NULL, approved_by text REFERENCES crm_members(id), approved_at timestamptz, status text NOT NULL, submitted_at timestamptz, confirmed_at timestamptz, provider_result_id text, error_code text, attempts integer NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX crm_write_request ON crm_writes (connection_id, request_id);
CREATE TABLE crm_events (id text PRIMARY KEY, connection_id text NOT NULL REFERENCES crm_connections(id), member_id text NOT NULL REFERENCES crm_members(id), kind text NOT NULL, at timestamptz NOT NULL, detail jsonb NOT NULL);
CREATE INDEX crm_events_connection ON crm_events (connection_id, at);
